/// <summary>
/// The form event handler class for ReqItemTable form.
/// </summary>
class METReqItemTableFormEventHandler
{    
}

Method.Source:
    /// <summary>
    /// Event handler for Alternate sell unit warehouse group
    /// </summary>
    /// <param name="sender">The sender object</param>
    /// <param name="e">Event arguments</param>
    [FormControlEventHandler(formControlStr(ReqItemTable, METAlternateSellUnitWH), FormControlEventType::Clicked)]
    public static void METAlternateSellUnitWH_OnClicked(FormControl sender, FormControlEventArgs e)
    {
        FormRun formRun = sender.formRun() as FormRun;
        FormDataSource reqItemTable_ds = formRun.dataSource();
        ReqItemTable reqItemTable = reqItemTable_ds.cursor();
        FormGroupControl alternateSalesGroup = sender as FormGroupControl;

        reqItemTable.ReqPOTypeActive = alternateSalesGroup.optionValue();

        formRun.initValueReqItemTable();
        formRun.enableFields();
    }
